          const currentTime = new Date();
          const timeExpiryRefreshToken = new Date(storagedTokenRefresh);

          // Se o token expirar, navega p/ tela de sessão expirada
          if (timeExpiryRefreshToken && currentTime >= timeExpiryRefreshToken) {
